package com.acme.k8s.cli;

import java.sql.*;
import java.util.*;
import java.util.regex.Pattern;
import java.util.regex.Matcher;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;

/**
 * K8s CronJob CLI tool for auditing pod resource usage.
 * Reads pod labels from environment (injected via downward API)
 * and logs resource metrics to PostgreSQL.
 */
public class ResourceAuditor {

    private static final Pattern SAFE_IDENTIFIER = Pattern.compile("^[a-zA-Z0-9_\\-\\.]+$");
    private static final int MAX_LABEL_LENGTH = 253; // K8s label max

    private final Connection conn;
    private final String schemaPrefix;

    public ResourceAuditor(Connection conn, String schemaPrefix) {
        this.conn = conn;
        this.schemaPrefix = schemaPrefix;
    }

    /**
     * Validates a Kubernetes label value per K8s naming conventions.
     * Must be alphanumeric with dashes, dots, underscores.
     */
    public static boolean isValidK8sLabel(String value) {
        if (value == null || value.isEmpty() || value.length() > MAX_LABEL_LENGTH) {
            return false;
        }
        return SAFE_IDENTIFIER.matcher(value).matches();
    }

    /**
     * Normalizes a namespace string for use in qualified table references.
     * Kubernetes namespaces follow DNS-1123 label format.
     */
    public static String normalizeNamespace(String ns) {
        if (ns == null) return "default";
        // Strip any surrounding whitespace
        String normalized = ns.strip();
        // Replace consecutive dots with single dot (defensive)
        normalized = normalized.replaceAll("\\.{2,}", ".");
        return normalized;
    }

    /**
     * Builds a fully-qualified table name from schema prefix and namespace.
     * Uses identifier quoting for safety.
     */
    public String buildTableRef(String namespace) {
        String ns = normalizeNamespace(namespace);
        // Quote the identifier to prevent injection
        String quotedSchema = quoteIdentifier(schemaPrefix);
        String quotedTable = quoteIdentifier("metrics_" + ns);
        return quotedSchema + "." + quotedTable;
    }

    /**
     * Standard SQL identifier quoting - doubles any internal quotes.
     */
    public static String quoteIdentifier(String identifier) {
        return "\"" + identifier.replace("\"", "\"\"") + "\"";
    }

    /**
     * Records a metric entry for a pod. Uses parameterized queries
     * for all VALUE positions to prevent SQL injection.
     */
    public void recordMetric(String podName, String namespace, 
                             String metricType, double value) throws SQLException {
        if (!isValidK8sLabel(podName)) {
            throw new IllegalArgumentException("Invalid pod name: " + podName);
        }
        if (!isValidK8sLabel(metricType)) {
            throw new IllegalArgumentException("Invalid metric type: " + metricType);
        }

        String tableRef = buildTableRef(namespace);

        // Parameterized query for values - table ref is quoted identifier
        String sql = "INSERT INTO " + tableRef + 
                     " (pod_name, metric_type, metric_value, recorded_at) " +
                     "VALUES (?, ?, ?, NOW())";

        try (PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setString(1, podName);
            ps.setString(2, metricType);
            ps.setDouble(3, value);
            ps.executeUpdate();
        }
    }

    /**
     * Retrieves aggregated metrics for a namespace within a time window.
     */
    public List<Map<String, Object>> getAggregatedMetrics(
            String namespace, String metricType, int hoursBack) throws SQLException {

        if (!isValidK8sLabel(metricType)) {
            throw new IllegalArgumentException("Invalid metric type");
        }
        if (hoursBack < 1 || hoursBack > 720) {
            throw new IllegalArgumentException("Hours must be 1-720");
        }

        String tableRef = buildTableRef(namespace);
        String sql = "SELECT pod_name, AVG(metric_value) as avg_val, " +
                     "COUNT(*) as sample_count FROM " + tableRef +
                     " WHERE metric_type = ? AND recorded_at > NOW() - INTERVAL '" + 
                     hoursBack + " hours' GROUP BY pod_name ORDER BY avg_val DESC";

        List<Map<String, Object>> results = new ArrayList<>();
        try (PreparedStatement ps = conn.prepareStatement(sql);
             ) {
            ps.setString(1, metricType);
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    Map<String, Object> row = new HashMap<>();
                    row.put("pod_name", rs.getString("pod_name"));
                    row.put("avg_value", rs.getDouble("avg_val"));
                    row.put("samples", rs.getInt("sample_count"));
                    results.add(row);
                }
            }
        }
        return results;
    }

    /**
     * Entrypoint for K8s CronJob execution.
     * Reads configuration from environment variables (set via ConfigMap/Secrets).
     */
    public static void main(String[] args) {
        String dbUrl = System.getenv("AUDIT_DB_URL");
        String dbUser = System.getenv("AUDIT_DB_USER");
        String dbPass = System.getenv("AUDIT_DB_PASS");
        String schema = Optional.ofNullable(System.getenv("AUDIT_SCHEMA")).orElse("k8s_audit");

        // Pod metadata injected via Downward API
        String podName = System.getenv("POD_NAME");
        String namespace = System.getenv("POD_NAMESPACE");

        if (dbUrl == null || podName == null) {
            System.err.println("Missing required environment variables");
            System.exit(1);
        }

        try (Connection conn = DriverManager.getConnection(dbUrl, dbUser, dbPass)) {
            ResourceAuditor auditor = new ResourceAuditor(conn, schema);

            // In production, metrics would come from /proc or cAdvisor API
            double cpuUsage = Runtime.getRuntime().availableProcessors() * Math.random();
            double memUsage = (double)(Runtime.getRuntime().totalMemory() - 
                              Runtime.getRuntime().freeMemory()) / (1024 * 1024);

            auditor.recordMetric(podName, namespace, "cpu_millicores", cpuUsage * 1000);
            auditor.recordMetric(podName, namespace, "memory_mb", memUsage);

            System.out.println("Metrics recorded successfully for pod: " + podName);
        } catch (Exception e) {
            System.err.println("Audit failed: " + e.getMessage());
            System.exit(2);
        }
    }
}
